use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::time::Instant;

use chrono::Local;
use clap::{Parser, ValueEnum};
use serde::Deserialize;

const AFTER_HELP: &str = "If your .git directory is a child of your project directory (most common, such as /myproject/.git)\nAND not in the current working directory (i.e you need to use --work-tree or --git-dir) you only\nneed to specify either the --work-tree (i.e. /myproject) OR --git-dir (i.e. /myproject/.git), you\ndon't need to use both.\n\nIf using the --config to specify a clog configuration TOML file NOT in the current working directory\n(meaning you need to use --work-tree or --git-dir) AND the TOML file is inside your project\ndirectory (i.e. /myproject/.clog.toml) you do not need to use --work-tree or --git-dir.";

#[derive(Copy, Clone, Debug, Eq, PartialEq, ValueEnum)]
