    Markdown,
    Json,
}

#[derive(Copy, Clone, Debug, Eq, PartialEq, ValueEnum)]
enum LinkStyle {
    Github,
    Gitlab,
    Stash,
    Cgit,
}

#[derive(Debug, Parser)]
#[command(
    name = "clog",
    bin_name = "executable",
    version = "0.10.0",
    about = "a conventional changelog for the rest of us",
    long_about = None,
    after_help = AFTER_HELP
)]
struct Cli {
    #[arg(
        short = 'r',
        long = "repository",
        value_name = "URL",
        help = "Repository used for generating commit and issue links (without the .git,\n                          e.g. https://github.com/thoughtram/clog)"
    )]
    repository: Option<String>,

    #[arg(short = 'f', long = "from", value_name = "COMMIT", help = "e.g. 12a8546")]
    from: Option<String>,

    #[arg(
        short = 'T',
        long = "format",
        value_name = "STR",
        default_value = "markdown",
        help = "The output format, defaults to markdown"
    )]
    format: OutputFormat,

    #[arg(
        short = 'M',
        long = "major",
        action = clap::ArgAction::SetTrue,
        help = "Increment major version by one (Sets minor and patch to 0)"
    )]
    major: bool,

    #[arg(
        short = 'g',
        long = "git-dir",
        value_name = "PATH",
        help = "Local .git directory (defaults to \"$(pwd)/.git\")"
    )]
    git_dir: Option<PathBuf>,

    #[arg(
        short = 'w',
        long = "work-tree",
        value_name = "PATH",
        help = "Local working tree of the git project (defaults to \"$(pwd)\")"
    )]
    work_tree: Option<PathBuf>,

    #[arg(
        short = 'm',
        long = "minor",
        action = clap::ArgAction::SetTrue,
        help = "Increment minor version by one (Sets patch to 0)"
    )]
    minor: bool,

    #[arg(
        short = 'p',
        long = "patch",
        action = clap::ArgAction::SetTrue,
        help = "Increment patch version by one"
    )]
    patch: bool,

    #[arg(short = 's', long = "subtitle", value_name = "STR", help = "")]
    subtitle: Option<String>,

    #[arg(
        short = 't',
        long = "to",
        value_name = "COMMIT",
        default_value = "HEAD",
        help = "e.g. 8057684"
    )]
    to: String,

    #[arg(
        short = 'o',
        long = "outfile",
        value_name = "PATH",
        help = "Where to write the changelog (Defaults to stdout when omitted)"
    )]
    outfile: Option<PathBuf>,

    #[arg(
        short = 'c',
        long = "config",
        value_name = "COMMIT",
        default_value = ".clog.toml",
        help = "The Clog Configuration TOML file to use"
    )]
    config: PathBuf,

    #[arg(
        short = 'i',
        long = "infile",
        value_name = "PATH",
        conflicts_with = "changelog",
        help = "A changelog to append to, but *NOT* write to (Useful in conjunction with\n                          --outfile)"
    )]
    infile: Option<PathBuf>,

    #[arg(long = "setversion", value_name = "VER", help = "e.g. 1.0.1")]
    setversion: Option<String>,

    #[arg(
        short = 'F',
        long = "from-latest-tag",
        action = clap::ArgAction::SetTrue,
        help = "use latest tag as start (instead of --from)"
    )]
    from_latest_tag: bool,

