    )]
    changelog: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
struct ConfigFile {
    clog: Option<toml::Table>,
}

enum Destination {
    Stdout,
    File(PathBuf),
}

fn main() -> ExitCode {
    let started = Instant::now();
    let cli = Cli::parse();

    if let Err(message) = validate_config(&cli.config) {
        return runtime_error(message);
    }

    if cli.setversion.is_none() && (cli.major || cli.minor || cli.patch) {
        return runtime_error(
            "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.",
        );
    }

    let header = Header {
        version: cli.setversion.clone(),
        subtitle: cli.subtitle.clone(),
        date: Local::now().format("%F").to_string(),
    };

    let old_contents = match read_old_contents(&cli) {
        Ok(contents) => contents,
        Err(message) => return runtime_error(message),
    };

    let destination = destination_for(&cli);
    let payload = match cli.format {
        OutputFormat::Markdown => {
            render_markdown(&header, old_contents.as_deref(), matches!(destination, Destination::Stdout))
        }
        OutputFormat::Json => {
            render_json(&header, old_contents.as_deref(), matches!(destination, Destination::Stdout))
        }
    };

    match destination {
        Destination::Stdout => {
            let mut stdout = io::stdout().lock();
            if stdout.write_all(payload.as_bytes()).is_err() {
                return runtime_error("fatal I/O error with output file");
            }
            if write_status(&mut stdout, started.elapsed().as_millis()).is_err() {
                return runtime_error("fatal I/O error with output file");
            }
        }
        Destination::File(path) => {
            if fs::write(path, payload).is_err() {
                return runtime_error("fatal I/O error with output file");
            }
            let mut stdout = io::stdout().lock();
            if write_status(&mut stdout, started.elapsed().as_millis()).is_err() {
                return runtime_error("fatal I/O error with output file");
            }
        }
    }

    ExitCode::SUCCESS
}

fn write_status(out: &mut impl Write, elapsed_ms: u128) -> io::Result<()> {
    writeln!(out, "changelog written. (took {elapsed_ms} ms)")
}

fn validate_config(path: &Path) -> Result<(), &'static str> {
    let raw = fs::read_to_string(path).map_err(|_| "fatal I/O error with output file")?;
    let parsed: ConfigFile =
        toml::from_str(&raw).map_err(|_| "Failed to parse TOML configuration file")?;
    if parsed.clog.is_none() {
        return Err("Failed to parse TOML configuration file");
    }
    Ok(())
}

fn read_old_contents(cli: &Cli) -> Result<Option<String>, &'static str> {
    if let Some(path) = &cli.changelog {
        return Ok(Some(fs::read_to_string(path).unwrap_or_default()));
    }

    if let Some(path) = &cli.infile {
        return fs::read_to_string(path)
            .map(Some)
            .map_err(|_| "fatal I/O error with output file");
    }

    Ok(None)
}

fn destination_for(cli: &Cli) -> Destination {
    if let Some(path) = &cli.changelog {
        return Destination::File(path.clone());
    }

    if let Some(path) = &cli.outfile {
        return Destination::File(path.clone());
    }

    Destination::Stdout
}

struct Header {
    version: Option<String>,
    subtitle: Option<String>,
    date: String,
}

fn render_markdown(header: &Header, old_contents: Option<&str>, stdout_mode: bool) -> String {
    let version = header.version.as_deref().unwrap_or("");
    let subtitle = header.subtitle.as_deref().unwrap_or("");
    let mut out = String::new();
    out.push_str(&format!(
        "<a name=\"{version}\"></a>\n## {version} {subtitle} ({})\n",
        header.date
    ));
    if stdout_mode {
        out.push('\n');
    } else {
        out.push_str("\n\n\n\n");
    }
    if let Some(old_contents) = old_contents {
        out.push_str(old_contents);
    }
    out
}

fn render_json(header: &Header, old_contents: Option<&str>, stdout_mode: bool) -> String {
    let version = match &header.version {
        Some(value) => format!("Some({value:?})"),
        None => "None".to_string(),
    };
    let subtitle = match &header.subtitle {
        Some(value) => value.clone(),
        None => "null".to_string(),
    };
    let mut out = format!(
        "{{\"header\":{{\"version\":{version},\"patch_version\":false,\"subtitle\":{subtitle},\"date\":\"{}\"}},\"sections\":null}}",
        header.date
    );
    if stdout_mode {
        if let Some(old_contents) = old_contents {
            out.push_str(old_contents);
        }
    } else {
        out.push_str("\n\n\n");
        if let Some(old_contents) = old_contents {
            out.push_str(old_contents);
        }
    }
    out
}

fn runtime_error(message: &'static str) -> ExitCode {
    let _ = writeln!(io::stderr(), "\u{1b}[1;31merror:\u{1b}[0m {message}");
    ExitCode::from(1)
}
